function visualizar_conexiones(e,o){console.log(e.data),console.log(o);const a=[],s=[],l=new Map;e.data.forEach((e=>{l.has(e.ORIGEN_ID)||(l.set(e.ORIGEN_ID,!0),a.push({id:e.ORIGEN_ID,label:e.ORIGEN,group:"interfaz",shape:"box",color:"#FF9900"})),l.has(e.DESTINO_ID)||(l.set(e.DESTINO_ID,!0),a.push({id:e.DESTINO_ID,label:e.DESTINO,group:"interfaz",shape:"box",color:"#FF9900"}),s.push({from:e.ORIGEN_ID,to:e.DESTINO_ID,arrows:"to",label:e.TIPO_CONEXION,color:"#848484"}))}));var I={nodes:a,edges:s},r=document.getElementById("network");new vis.Network(r,I,{layout:{hierarchical:{enabled:!0,direction:o}},physics:{enabled:!1,solver:"forceAtlas2Based"}})}